public interface PaymentGateway {
    Receipt charge(Money amount);
}

public abstract class BasePaymentGateway implements PaymentGateway {
    private final AuditLog auditLog;

    protected BasePaymentGateway(AuditLog auditLog) {
        this.auditLog = auditLog;
    }

    public final Receipt charge(Money amount) {
        auditLog.record("charging " + amount);
        return doCharge(amount);
    }

    protected abstract Receipt doCharge(Money amount);
}

class CardGateway extends BasePaymentGateway {
    CardGateway(AuditLog log) { super(log); }
    protected Receipt doCharge(Money amount) { return Receipt.of(amount); }
}

PaymentGateway gateway = new CardGateway(auditLog);
gateway.charge(Money.of(10));

